import{_ as t,o as a,c as n,a0 as s}from"./chunks/framework.D4fUSYzX.js";const p=JSON.parse('{"title":"Commands","description":"The bun commands of the repository, the shared control gallery, and the guide screenshots.","frontmatter":{"title":"Commands","description":"The bun commands of the repository, the shared control gallery, and the guide screenshots."},"headers":[],"relativePath":"development/commands.md","filePath":"development/commands.md"}'),o={name:"development/commands.md"};function r(i,e,d,h,l,c){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>bun run dev</code></td><td>Start the control plane in watch mode</td></tr><tr><td><code>bun run test</code></td><td>Run the full test suite</td></tr><tr><td><code>bun run test:changed</code></td><td>Run only the test files the current changes affect</td></tr><tr><td><code>bun run gallery</code></td><td>Run the shared control gallery, using the real modules</td></tr><tr><td><code>bun run mutate</code></td><td>Run a Stryker mutation campaign over <code>src</code></td></tr><tr><td><code>bun run lint</code></td><td>Lint and check formatting with Biome</td></tr><tr><td><code>bun run fmt</code></td><td>Lint, format, and fix with Biome</td></tr><tr><td><code>bun run typecheck</code></td><td>Typecheck with TypeScript</td></tr><tr><td><code>bun run build</code></td><td>Compile one prebuilt binary of the control plane</td></tr><tr><td><code>bun run screenshots</code></td><td>Regenerate the guide screenshots from fixture state</td></tr></tbody></table><p><code>bun run dev</code> runs the source tree; it reads <code>config/development.toml</code> through <code>--config</code> and watches the tree while it runs. A change to a watched file restarts the control plane inside the same process, so the reload keeps the state file: the run gives the state lease back when the watch signals it, and the next boot takes the lease again. Only the files the run imports are watched, so the state file and the worktrees never trigger a restart.</p><h2 id="scoped-run" tabindex="-1">Scoped run <a class="header-anchor" href="#scoped-run" aria-label="Permalink to &quot;Scoped run&quot;">​</a></h2><p><code>bun run test:changed</code> is the suite, scoped: it runs only the test files that the current changes can affect, so a change to one or two files keeps the run short. It is a speed tool for iteration; the push gate stays the full suite.</p><p>The base ref defaults to <code>origin/main</code> and is overridable with the <code>TEST_CHANGED_BASE</code> environment variable, so work based on another branch scopes against its real base: <code>TEST_CHANGED_BASE=origin/feature bun run test:changed</code>. The run covers committed changes against the base, uncommitted edits, and untracked test files, and it works on a detached head, so a herdr worktree gets the same tool. A clean, up-to-date worktree matches nothing, and the run says so.</p><h2 id="mutation-testing" tabindex="-1">Mutation testing <a class="header-anchor" href="#mutation-testing" aria-label="Permalink to &quot;Mutation testing&quot;">​</a></h2><p><code>bun run mutate</code> rewrites one expression at a time in <code>src</code> and runs the suite against the rewritten copy, to answer the question a passing suite cannot: would the tests notice a wrong program. A full campaign takes hours, so it is not part of the push gate, and a run usually picks its own scope: <code>bun run mutate -- &quot;--mutate=src/domain/**&quot;</code>. See <a href="./mutation-testing.html">mutation testing</a> for what a campaign measures and what it costs, and <a href="./../adr/0055-mutation-testing-runs-on-the-bun-test-runner.html">ADR 0055</a> for the setup and the measured budget.</p><h2 id="prebuilt-binary" tabindex="-1">Prebuilt binary <a class="header-anchor" href="#prebuilt-binary" aria-label="Permalink to &quot;Prebuilt binary&quot;">​</a></h2><p><code>bun run build &lt;target&gt; --out &lt;dir&gt;</code> compiles the control plane into the standalone executable the release publishes (ADR 0056), for one target: <code>linux-x64</code>, <code>linux-x64-musl</code>, <code>linux-arm64</code>, <code>linux-arm64-musl</code>, <code>darwin-x64</code>, <code>darwin-arm64</code>, or <code>windows-x64</code>. It prints the usage line and the target list when it is called without them.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --omit=optional</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux-x64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dist/factory-$(node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;require(&#39;./package.json&#39;).version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)-linux-x64 --version</span></span></code></pre></div><p>The build adds the target&#39;s OpenTUI native cores when they are not in <code>node_modules</code>, with <code>--no-save</code>, and stops before the compile when the tree holds a core the target must not embed. The compile embeds every core it can resolve, so one build tree carries one target: after a leg for another target, <code>bun install --omit=optional</code> clears the leftover cores back to the release&#39;s tree, and the line the build prints names that command. The example above puts that install first because it is the step every release leg runs; a tree already carrying exactly the target&#39;s cores needs no reinstall. That add is what makes the core resolvable to the bundler, not a size measure: <code>@opentui/core</code> names eight platform packages in literal dynamic imports, and the bundler prunes the platform and arch tests per <code>--target</code> but cannot prune the libc test, which reads <code>process.env.OPENTUI_LIBC</code>. So a Linux leg places both libc variants and its binary carries both, and a Darwin or Windows leg builds with one. Each release leg builds one target on a clean runner (<code>bun install --omit=optional</code> first), and <code>bun run build</code> is the same command the leg runs; the measured core count and byte size per target are in <a href="https://github.com/SeriousJul/my-little-software-factory/blob/main/docs/verification/release.md" target="_blank" rel="noreferrer">the release record</a>. The app&#39;s runtime libraries are development dependencies: the binary carries them, and the npm package that installs the binary carries nothing but the installer.</p><h2 id="shared-control-gallery" tabindex="-1">Shared control gallery <a class="header-anchor" href="#shared-control-gallery" aria-label="Permalink to &quot;Shared control gallery&quot;">​</a></h2><p><code>bun run gallery</code> opens the shared control gallery: every control the control plane owns, drawn by the production modules and answering the production keys. <code>Tab</code> shows the next example, and each one names its own state - normal and focused, invalid, unavailable, loading, Type-ahead search, and narrow. Pass an example name to land on it: <code>bun run gallery -- fields</code>. The gallery reads no config file, opens no state, and starts no Agent, and the same examples are exercised by <code>bun run test</code>, so a gallery row cannot become an imitation of the control. See <a href="./shared-controls.html">the shared control standard</a>.</p><h2 id="regenerating-the-screenshots" tabindex="-1">Regenerating the screenshots <a class="header-anchor" href="#regenerating-the-screenshots" aria-label="Permalink to &quot;Regenerating the screenshots&quot;">​</a></h2><p><code>bun run screenshots</code> rebuilds the images the <a href="./../operation/main-view.html">operation guide</a> shows: the fixture world, the production binary on a pseudo-terminal, the production keys, and the cell-grid render. The drift test in <code>bun run test</code> reruns the same path and fails when a committed image no longer matches the screen, so a screen change always lands with its image.</p>`,16)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
